  salesLetter_benefit1Label: 'Höherer Umsatz:',
  salesLetter_benefit1Text: 'Erweitern Sie Ihre digitale Präsenz, erreichen Sie mehr Gäste und steigern Sie den Verkauf mit einfacher Online-Bestellung.',
  salesLetter_benefit2Label: 'Kundentreue:',
  salesLetter_benefit2Text: 'Schaffen Sie Treue mit exklusiven Angeboten und einem einfachen Bestellprozess.',
  salesLetter_benefit3Label: 'Markenaufbau:',
  salesLetter_benefit3Text: 'Stärken Sie Ihre Marke mit einer an Ihr Branding angepassten App.',
  salesLetter_closingText: 'Gerne komme ich für eine Demonstration vorbei, um zu besprechen, wie sich unsere Lösung an die besonderen Bedürfnisse von {name} anpassen lässt. Schreiben Sie mir gerne eine E-Mail oder rufen Sie mich unter 988 65 120 an, um einen Termin zu vereinbaren.',
  salesLetter_greeting: 'Sehr geehrtes Team von',
  salesLetter_intro: 'Wir haben {name} sorgfältig ausgewählt, weil wir überzeugt sind, dass Sie von einer von uns angebotenen massgeschneiderten Lösung erheblich profitieren werden – einer eigenen Bestell-App.',
  salesLetter_okamLogoAlt: 'Logo',
  salesLetter_paragraph2: 'Wir bei Okam haben ein einzigartiges System entwickelt, mit dem Restaurants wie das Ihre eine eigene, an die Marke angepasste Bestell-App lancieren können. Diese App stärkt nicht nur Ihre Marke, sondern bietet auch eine direkte und verbesserte Verbindung zu Ihren Gästen und steigert gleichzeitig den Umsatz. Unsere Partner, wie Jungel Pizza, berichten von beträchtlichem Wachstum und höherer Kundenzufriedenheit dank unseres Dienstes.',
  salesLetter_priceText: 'Unser regulärer Preis für diesen Dienst beträgt 2000 CHF/Monat. Für {name} möchten wir Ihnen jedoch ein besonderes Angebot machen, das noch besser ist. Wir berechnen einen tiefen Monatspreis und sind stolz darauf, das zu bieten, was wir für die beste Benutzerfreundlichkeit der Schweiz für Bestell-Apps halten.',
