  meals_setup_intro: 'Hier wird eine Firma eingerichtet: die Firma selbst, ihre Vereinbarung mit diesem Standort, ihr Essensprogramm samt Regelwerk und ihre Einladungen.',
  meals_setup_no_ordering: 'Nichts hier ermöglicht einer angestellten Person zu bestellen. Die Bestellung auf Firmenkonto liegt hinter einem eigenen Flag, und keine Okam-App bietet ein Firmenkonto als Zahlungsart an. Ein hier eingerichtetes Programm macht das Mittagessen also nicht kaufbar.',
