  meals_corridor_title: 'Die Vereinbarung mit diesem Standort',
  meals_corridor_intro: 'Die Vereinbarung verbindet Firma, Standort und Währung. Alles Weitere im Modul hängt daran.',
  meals_corridor_exists: 'Diese Firma hat hier bereits eine aktive Vereinbarung. Eine zweite für dieselbe Firma, denselben Standort und dieselbe Währung wird abgelehnt — die erste muss beendet werden, und das geht von diesem Bildschirm aus nicht.',
