  meals_people_title: 'Personen',
  meals_mig17_title: 'Ohne Personalreferenz erzeugt diese Einladung eine Mitgliedschaft, die sich später nicht mehr kennzeichnen lässt.',
  meals_mig17_body: 'Die Referenz kann nur hier erfasst werden, bei der Einladung. Eine ohne sie eingelöste Mitgliedschaft kann sie nie mehr erhalten: die Einladung ist verbraucht, und die Zeilen einer abgeschlossenen Monatsabrechnung sind gesperrt. Die Person erscheint dann auf jeder Zeile der Firmenrechnung als blosse Kennung, für immer.',
  meals_mig17_ack: 'Mir ist klar, dass diese Einladung eine Mitgliedschaft erzeugt, die auf jeder künftigen Monatsabrechnung als blosse Kennung erscheint, und dass sich das später nicht korrigieren lässt.',
