  meals_token_not_sent_body: 'Okam hat keine Möglichkeit, dieses Token zuzustellen — weder per E-Mail noch per SMS. Es existiert hier und sonst nirgends. Damit die Einladung jemanden erreicht, musst du das Token selbst weitergeben, über einen Kanal, dem du vertraust.',
