  meals_token_claim_screen: 'Wer den Code erhält, löst ihn selbst unter {link} ein. Dort wird der Code eingefügt und die Anmeldung durchgeführt. Okam schickt nichts zu, die Adresse muss also zusammen mit dem Code weitergegeben werden.',
