  meals_token_done: 'Ich habe das Token weitergegeben',
  meals_token_once_note: 'Das Token wird nicht erneut angezeigt. Keine Route kann es ein zweites Mal liefern — ist es weg, widerrufe die Einladung und stelle eine neue aus.',
  meals_invite_title: 'Jemanden einladen',
  meals_invite_intro: 'Gib eine E-Mail-Adresse oder eine Telefonnummer an. Der Kontakt ist nicht bloss eine Beschriftung: wer die Einladung einlöst, muss als diese Person angemeldet sein.',
