  meals_field_employee_ref_hint: 'Die firmeneigene Referenz für diese Person — Personalnummer, Kostenstelle oder Initialen. Sie landet auf jeder Zeile der Monatsabrechnung und im Export, den die Buchhaltung öffnet. Nie eine Sozialversicherungsnummer; der Server weist sie ab. Nur jetzt erfassbar.',
