  meals_col_account: 'Benutzerkonto',
  meals_members_display_note: 'Diese Spalte ist genau das, was auf jeder Zeile der Monatsabrechnung der Firma landet: die firmeneigene Personalreferenz, sofern angegeben, sonst die Mitgliedschafts-ID. Das Modul kennt keine Namen. Zeilen mit «keine Personalreferenz» lassen sich nicht korrigieren — die Einladung ist verbraucht, abgeschlossene Abrechnungen sind gesperrt.',
