  // Absichtlich kürzer als der Seitentitel: 'Schulung und Eigenkontrolle' ist, was die Seite tut,
  // 'Schulung' ist, wonach man im Menü sucht.
  nav_training_courses: 'Schulung',
  // "Eigenkontrolle" ist dieselbe Behauptung, die OD-6 auf Norwegisch verbietet ("internkontroll"),
  // also entfällt sie ebenfalls: HACCP-Gefahrenanalyse, Rückverfolgbarkeit und Allergeninformationen
  // fehlen im Domänenmodell selbst bei vollem Umfang. Wird 'Training & Routines' mit TR8/TR-B6.
  trn_page_title: 'Schulung',
  trn_page_intro: 'Aus einem Kurs wird ein Nachweis: Kurs anlegen, eine Version veröffentlichen, zuweisen, den Abschluss erfassen — und dann nachschlagen, was die Person tatsächlich besitzt.',
  trn_reload: 'Neu laden',

  trn_gate_unknown: 'Der Kontextaufruf hat nicht geantwortet. Wir wissen nicht, ob das Schulungsmodul für diesen Betrieb aktiv ist, und sagen deshalb nichts darüber.',
  trn_gate_unauthenticated: 'Sie sind nicht an der API angemeldet.',
  trn_gate_forbidden: 'Der Server hat abgelehnt. Er unterscheidet nicht zwischen einem Betrieb, den Sie nicht verwalten, und einem Betrieb, den es nicht gibt — welches von beidem zutrifft, lässt sich nicht sagen.',
  trn_gate_invisible: 'Das Schulungsmodul ist für diesen Betrieb nicht eingeschaltet. Der Server hat selbst geantwortet, das Modul ist also ausgerollt — es ist hier nur unsichtbar, bis eine Betreiberin training.setup einschaltet.',
  trn_gate_unreachable: 'Keine Antwort vom Schulungsmodul. Die Route existiert in dieser Umgebung nicht, also lässt sich über den Betrieb nichts sagen.',

  trn_footnote_zone: 'Zeitstempel erscheinen in der Zeitzone des Betriebs ({zone}), so wie der Server sie aufgelöst hat. Datumsangaben (ausgestellt, läuft ab, fällig) erscheinen als der erfasste Tag, ohne Umrechnung.',
  trn_footnote_zone_fallback: 'Der Betrieb hat keine gültige Zeitzone. Der Server ist auf {zone} zurückgefallen, und die Zeitstempel darunter erscheinen darin. Datumsangaben erscheinen als der erfasste Tag, ohne Umrechnung.',
  trn_footnote_zone_utc: 'Die Zeitzone des Betriebs ist unbekannt, deshalb erscheinen Zeitstempel in UTC. Datumsangaben erscheinen als der erfasste Tag, ohne Umrechnung.',
  trn_footnote_scope: 'Diese Seite ist der Nachweis über Kurse, Zuweisungen, Abschlüsse und Zertifikate. Entwürfe bearbeiten, Versionen stilllegen, Zertifikate korrigieren und die Ablaufliste sind hier nicht angebunden.',

  trn_err_validation: 'Der Server hat den Inhalt der Anfrage abgelehnt.',
  trn_err_forbidden: 'Der Server hat abgelehnt. Er unterscheidet fehlenden Zugriff nicht von einem Betrieb, den es nicht gibt.',
  trn_err_not_found: 'Der Server hat die Ressource nicht gefunden. Die Antwort ist dieselbe, ob sie fehlt, zu einem anderen Betrieb gehört oder das Modul aus ist — welches davon, wissen wir nicht.',
  trn_err_idem_mismatch: 'Derselbe Idempotenzschlüssel wurde mit anderem Inhalt verwendet. Es wurde nichts geschrieben.',
  trn_err_idem_inflight: 'Eine identische Anfrage ist bereits unterwegs. Neu laden und erneut versuchen.',
  trn_err_immutable: 'Die Version ist kein Entwurf. Der Inhalt einer veröffentlichten Version ist eingefroren — eine Änderung ist eine neue Version.',
  trn_err_flag_off: 'Dieser Bereich ist für den Betrieb ausgeschaltet. Lesen antwortet weiterhin, Schreiben nicht.',
  trn_err_unknown: 'Etwas ist schiefgelaufen, und der Fehler kam nicht vom Schulungsmodul.',
  // Nur für die beiden Schreibvorgänge, die eine Person binden. Jede andere 400 dieser Routen
  // verhindert das Formular vor dem Senden, also bleibt genau diese Ursache übrig — siehe `fail`.
  trn_err_person_unknown: 'Die ID bezeichnet keine bekannte Person, es wurde nichts abgelegt. Prüfen Sie sie gegen die Mitarbeiterliste oder gegen die Personen-ID, die die Personalplanung anzeigt.',

  trn_context_title: 'Modulstatus',
  trn_context_zone: 'Zeitzone',
  trn_context_zone_fallback: '(Ersatz)',
