  trn_context_seam: 'Kompetenzkopplung zur Personalplanung',
  trn_seam_bound: 'Gekoppelt',
  trn_seam_unbound: 'Nicht gekoppelt',

  trn_flags_title: 'Funktionsschalter',
  trn_flags_note: 'Das sind die Antworten des Servers, keine Vermutung. Bei ausgeschaltetem Schalter antwortet Lesen weiterhin — Schreiben wird abgelehnt.',
  trn_flag_on: 'An',
  trn_flag_off: 'Aus',
