  nav_workforce_personnel_list: 'Personalliste',
  wfpl_page_title: 'Personalliste',
  wfpl_page_intro: 'Wer sich jetzt am Arbeitsort befindet und wer am selben Tag zuvor da war — mit dem Beginn und dem Ende des Arbeitstages. Die Liste muss am Arbeitsort verfügbar sein und sich sofort auf Papier ausdrucken lassen.',
  wfpl_context_failed: 'Zeitzone und Berechtigungen des Betriebs konnten nicht gelesen werden. Die Seite zeigt lieber nichts, als zu raten.',
  wfpl_no_capability: 'Sie besitzen in diesem Betrieb nicht die Berechtigung WorkforceManager. Die Personalliste wird ausschliesslich mit dieser gelesen — weder Betriebsadministration noch Power User genügt für sich allein.',
