  gp_state_inprogress: 'Begonnen',
  gp_state_fulfilled: 'Ausgeführt',
  gp_state_rejectedwithreason: 'Abgelehnt',
  gp_state_unknown: 'Unbekannt',
  gp_reference: 'Referenz {reference} · eingegangen {when}',
  gp_contact: 'Kontaktpunkt {id}',
  gp_due: 'Frist {when}',
  gp_days_left: 'Noch {days} Tage',
  gp_days_left_one: 'Noch ein Tag',
  gp_due_today: 'Die Frist läuft heute ab.',
  gp_overdue_by: 'Die Frist ist vor {days} Tagen abgelaufen.',
  gp_overdue_today: 'Die Frist ist heute abgelaufen.',
  gp_overdue_by_one: 'Die Frist ist gestern abgelaufen.',
  gp_due_unknown: 'Der Dienst hat für diese Anfrage keine Frist mitgeteilt, deshalb wird keine angezeigt. Diese Seite berechnet sie nicht selbst — ein erfundenes Datum könnte von dem abweichen, das dem Gast zugesagt wurde. Laden Sie neu und behandeln Sie die Anfrage bis dahin als dringend.',
  gp_resolved_at: 'Abgeschlossen {when}',
  gp_notice_submittedtotransport: 'Der Mailanbieter hat die Nachricht an den Gast angenommen. Ob sie angekommen ist, wissen wir nicht — das kann nur der Anbieter sagen.',
  gp_notice_notattempted: 'Es wurde keine Nachricht gesendet. Die Adresse war bereits gelöscht, es gab niemanden mehr zu benachrichtigen.',
  gp_notice_attemptedandfailed: 'Eine Nachricht wurde versucht und abgewiesen. Es wurde nichts gelöscht, und die Anfrage ist weiterhin offen.',
  gp_notice_none: 'Zu dieser Anfrage ist keine Nachrichten-Quittung erfasst.',
  gp_fulfil: 'Ausführen',
  gp_fulfil_erasure_warning: 'Das lässt sich nicht rückgängig machen. Der Gast wird zuerst über die ausgeführte Löschung informiert, danach wird die Adresse gelöscht — oder zur Löschung vorgemerkt, falls ein anderes Lokal noch gültige Einwilligung für denselben Kontaktpunkt hält. Diese Liste sagt nicht, welcher der beiden Fälle eingetreten ist.',
  gp_fulfil_access_warning: 'Der Dienst erstellt die Historie des Gastes und sendet sie an dessen Adresse. Nichts davon wird auf diesem Bildschirm angezeigt, und der Export wird nicht gespeichert.',
  gp_confirm: 'Ja, ausführen',
  gp_cancel: 'Abbrechen',
  gp_reject: 'Ablehnen',
  gp_reason_label: 'Begründung',
  gp_reason_placeholder: 'Warum wird abgelehnt? Keine personenbezogenen Daten eintragen.',
  gp_reason_required: 'Eine Ablehnung braucht eine Begründung. Sie bleibt an der Anfrage vermerkt.',
  gp_working: 'Wird ausgeführt …',
  gp_toast_fulfilled: 'Anfrage {reference} wurde ausgeführt.',
  gp_toast_rejected: 'Anfrage {reference} wurde abgelehnt, die Begründung ist erfasst.',
  gp_error_not_found: 'Diese Anfrage gibt es hier nicht. Der Dienst antwortet gleich für eine Anfrage, die nicht existiert, und eine, die zu einem anderen Lokal gehört.',
  gp_error_reason_required: 'Eine Ablehnung braucht eine Begründung. Es wurde nichts gespeichert.',
  gp_error_invalid_resolution: 'Das Ergebnis muss entweder ausgeführt oder abgelehnt sein. Es wurde nichts gespeichert.',
  gp_error_unattributed: 'Wir konnten nicht feststellen, wer Sie sind. Eine Löschung wird nie ohne den Namen der anordnenden Person erfasst, daher wurde nichts getan.',
  gp_error_notice_undeliverable: 'Der Mailanbieter hat die dem Gast geschuldete Nachricht nicht angenommen. Es wurde nichts gelöscht, die Anfrage bleibt offen, und Sie können es erneut versuchen.',
  gp_error_body_required: 'Die Anfrage enthielt keinen Inhalt. Es wurde nichts gespeichert.',
